import React from 'react';
import { createRoot } from 'react-dom/client';
import { MemoryRouter } from 'react-router-dom';
import '../../src/index.css';
import { Workspace } from '../../src/components/workspace/Workspace';
import { useWorkspaceStore } from '../../src/store/workspace-store';
import { useFocusModeStore } from '../../src/store/focus-mode-store';
import { useActiveSessionStore } from '../../src/store/active-session-store';
window.history.replaceState({}, '', '/instances/test/sessions');
useActiveSessionStore.getState().setActiveSession('test', 'session-a');
Object.assign(window, { focusedPane: () => useFocusModeStore.getState().paneId, openDesktop: () => { const store = useWorkspaceStore.getState(); const chat = store.openTab('sessions'); return store.splitPane(chat!, 'desktop', 'right'); } });
createRoot(document.getElementById('root')!).render(<MemoryRouter initialEntries={['/instances/test/sessions']}><div style={{height:'100vh'}}><Workspace instanceName="test" /></div></MemoryRouter>);
